  const failed = arr.find(j => String(j.conclusion || j.status || "").toLowerCase() === "failure" || String(j.conclusion || "").toLowerCase() === "failed");
  if (!failed) throw new Error("No failed job found in workflow run 9");
  const required = logTool.requiredInputKeys || [];
  const args = {};
  for (const k of required) {
    if (/job.*id|job_id/i.test(k)) args[k] = failed.id;
    else if (/run.*id|run_id/i.test(k)) args[k] = 9;
    else if (/owner/i.test(k) && failed.owner) args[k] = failed.owner;
    else if (/repo/i.test(k) && failed.repo) args[k] = failed.repo;
  }
  const logs = await connecta.call(logTool.address, args);
  if (Array.isArray(logs)) return logs.map(String);
  if (Array.isArray(logs.lines)) return logs.lines.map(String);
  if (typeof logs === "string") return logs.split(/\r?\n/);
  if (typeof logs.content === "string") return logs.content.split(/\r?\n/);
