    if (Array.isArray(x)) return x;
    if (x && typeof x === "object") {
      for (const k of ["jobs","items","results","data"]) if (Array.isArray(x[k])) return x[k];
      for (const v of Object.values(x)) { const a = scan(v); if (a.length) return a; }
    }
    return [];
  };
  const jobs = scan(jobsData);
  const failed = jobs.find(j => /fail/i.test(String(j.conclusion ?? j.status ?? j.result ?? "")));
  if (!failed) throw new Error("No failed job found in run 9");
