    else throw new Error("Missing required input for logs tool: " + k);
  }
  const logs = await connecta.call(logTool.address, req2);
  let lines;
  if (Array.isArray(logs)) lines = logs;
  else if (typeof logs === "string") lines = logs.split(/\r?\n/);
