  const candidates = s.tools.filter(t => /record|collection|determin/i.test((t.address||"")+" "+(t.description||"")));
  if (!candidates.length) throw new Error("No compatible records tool");
  const t = candidates.find(x => (x.requiredInputKeys||[]).length === 0) || candidates[0];
  const args = {};
  for (const k of (t.requiredInputKeys||[])) {
    if (/limit|count|size/i.test(k)) args[k] = 120;
    else throw new Error("Unsupported required input: "+k);
  }
  const data = await connecta.call(t.address, args);
  const arr = Array.isArray(data) ? data : (data.records || data.items || data.results || data.data);
  if (!Array.isArray(arr)) return {chosen:t.address, shape:Object.keys(data||{})};
  const out = {};
  for (const rec of arr.slice(0,120)) {
    const g = rec.group ?? rec.groupName ?? rec.category;
    const score = Number(rec.score);
    if (!(g in out)) out[g] = {recordCount:0, scoreSum:0};
    out[g].recordCount++;
    out[g].scoreSum += score;
  }
  return out;
}

