async () => {
  const found = await connecta.search({query:"deterministic collection records group score", safety:"readOnly", includeSchemas:"compact"});
  const candidates = found.tools || [];
  const tool = candidates.find(t => {
    const s = (t.address + " " + (t.description || "")).toLowerCase();
    return s.includes("determin") && (s.includes("record") || s.includes("collection"));
  });
  if (!tool) throw new Error("No matching deterministic collection tool. Candidates: " + candidates.map(t=>t.address).join(", "));
  const args = {};
  for (const k of (tool.requiredInputKeys || [])) {
    if (/count|limit|size/i.test(k)) args[k] = 120;
    else throw new Error("Unresolved required key " + k + " for " + tool.address);
  }
  const data = await connecta.call(tool.address, args);
  const rows = Array.isArray(data) ? data : (data.records || data.items || data.results || data.data);
  if (!Array.isArray(rows)) throw new Error("Unexpected data shape from " + tool.address + ": " + JSON.stringify(data).slice(0,500));
  const out = {};
  for (const row of rows) {
    const g = row.group;
    if (!(g in out)) out[g] = {record_count: 0, score_sum: 0};
    out[g].record_count += 1;
    out[g].score_sum += Number(row.score);
  }
  return {tool: tool.address, rowCount: rows.length, groups: out};
}

