async () => {
  const [runSearch, docSearch] = await Promise.all([
    connecta.search({ query: "workflow run response", safety: "readOnly", includeSchemas: "compact" }),
    connecta.search({ query: "document search", safety: "readOnly", includeSchemas: "compact" })
  ]);
  const runTool = runSearch.tools.find(t =>
    /workflow/i.test(t.address + " " + t.description) &&
    /run/i.test(t.address + " " + t.description) &&
    Array.isArray(t.requiredInputKeys) &&
    t.requiredInputKeys.length === 1
  );
  const docTool = docSearch.tools.find(t =>
    /document/i.test(t.address + " " + t.description) &&
    /search/i.test(t.address + " " + t.description) &&
    Array.isArray(t.requiredInputKeys) &&
    t.requiredInputKeys.length === 1
  );
  if (!runTool) throw new Error("No compatible workflow-run retrieval tool found");
  if (!docTool) throw new Error("No compatible document search tool found");
  const runKey = runTool.requiredInputKeys[0];
  const docKey = docTool.requiredInputKeys[0];
  const calls = await connecta.batch([
    { address: runTool.address, args: { [runKey]: 9 } },
    { address: docTool.address, args: { [docKey]: "staged customer rollout" } }
  ]);
  if (!calls[0].ok) throw new Error("Workflow run fetch failed: " + calls[0].error);
  if (!calls[1].ok) throw new Error("Document search failed: " + calls[1].error);
  const docData = calls[1].data;
  const resultArray = Array.isArray(docData) ? docData :
    (Array.isArray(docData.results) ? docData.results :
    (Array.isArray(docData.matches) ? docData.matches :
    (Array.isArray(docData.documents) ? docData.documents : null)));
  if (!resultArray) throw new Error("Document search response did not contain a declared result array");
  return { workflowRun: calls[0].data, launchPlanMatches: resultArray };
}

