async () => {
  const found = await connecta.search({ query: "deterministic collection 120 records group score", safety: "readOnly", includeSchemas: "compact" });
  const candidates = found.tools || [];
  const tool = candidates.find(t => /deterministic|collection|record/i.test((t.address || "") + " " + (t.description || "")));
  if (!tool) throw new Error("No deterministic collection tool found: " + JSON.stringify(candidates));
  const args = {};
  for (const key of (tool.requiredInputKeys || [])) {
    if (/count|limit|size|records/i.test(key)) args[key] = 120;
    else throw new Error("Unsupported required input " + key + " for " + tool.address);
  }
  const data = await connecta.call(tool.address, args);
  const rows = Array.isArray(data) ? data
    : Array.isArray(data.records) ? data.records
    : Array.isArray(data.items) ? data.items
    : Array.isArray(data.data) ? data.data
    : null;
  if (!rows) throw new Error("Unknown collection shape for " + tool.address + ": " + JSON.stringify(data).slice(0,1000));
  const out = {};
  for (const row of rows) {
    const group = row.group ?? row.groupName ?? row.category;
    const score = row.score;
    if (group == null || typeof score !== "number") throw new Error("Unexpected row: " + JSON.stringify(row));
    if (!out[group]) out[group] = { recordCount: 0, scoreSum: 0 };
    out[group].recordCount++;
    out[group].scoreSum += score;
  }
  return { tool: tool.address, rowCount: rows.length, aggregate: out };
}

