  const docCandidates = docSearch.tools.filter(t => /document/i.test(t.address + " " + (t.description || "")) && /search/i.test(t.address + " " + (t.description || "")));
  const runTool = runCandidates.find(t => (t.requiredInputKeys || []).some(k => /run.?id|id/i.test(k))) || runCandidates[0];
