  const sl = await connecta.search({ connector: "builds", query: "download job logs", safety: "readOnly", includeSchemas: "compact" });
  const jt = (sj.tools || []).find(t => /list|get/i.test(t.address||"") && /job/i.test((t.address||"")+" "+(t.description||"")) && !/rerun|retry|cancel|delete/i.test((t.address||"")+" "+(t.description||"")));
  const lt = (sl.tools || []).find(t => /log/i.test((t.address||"")+" "+(t.description||"")) && /job/i.test((t.address||"")+" "+(t.description||"")) && !/rerun|retry|cancel|delete/i.test((t.address||"")+" "+(t.description||"")));
  if (!jt || !lt) throw new Error("Required read tools not found");
  const makeArgs = (t, value) => {
    const ks = t.requiredInputKeys || [];
    if (ks.length !== 1) throw new Error("Unexpected required inputs for " + t.address + ": " + JSON.stringify(ks));
    return { [ks[0]]: value };
  };
  const jobsRaw = await connecta.call(jt.address, makeArgs(jt, 9));
  const jobs = Array.isArray(jobsRaw) ? jobsRaw : (jobsRaw.jobs || jobsRaw.items || jobsRaw.results || []);
  const failed = jobs.find(j => ["failure","failed"].includes(String(j.conclusion || j.status || "").toLowerCase()));
  if (!failed) throw new Error("Failed job not found");
  const logsRaw = await connecta.call(lt.address, makeArgs(lt, failed.id));
  if (Array.isArray(logsRaw)) return logsRaw.map(String);
  if (Array.isArray(logsRaw.lines)) return logsRaw.lines.map(String);
  const body = typeof logsRaw === "string" ? logsRaw : (logsRaw.log || logsRaw.logs || logsRaw.content || "");
  return String(body).split(/\r?\n/);
}

async () => {
  const sj = await connecta.search({ connector: "builds", query: "workflow jobs", safety: "readOnly", includeSchemas: "compact", limit: 20 });
  const sl = await connecta.search({ connector: "builds", query: "job log lines", safety: "readOnly", includeSchemas: "compact", limit: 20 });
  const scoreJobs = t => {
    const x=((t.address||"")+" "+(t.description||"")).toLowerCase();
    return (x.includes("workflow")?8:0)+(x.includes("run")?4:0)+(x.includes("jobs")?5:0)+(x.includes("list")?3:0)-(x.includes("rerun")?30:0);
  };
  const scoreLogs = t => {
    const x=((t.address||"")+" "+(t.description||"")).toLowerCase();
    return (x.includes("job")?5:0)+(x.includes("log")?8:0)+(x.includes("line")?3:0)-(x.includes("rerun")?30:0);
  };
  const jt=[...(sj.tools||[])].sort((a,b)=>scoreJobs(b)-scoreJobs(a))[0];
  const lt=[...(sl.tools||[])].sort((a,b)=>scoreLogs(b)-scoreLogs(a))[0];
  if (!jt || !lt) throw new Error("Required tools not found");
  const argFor = (t,v) => {
    const ks=t.requiredInputKeys||[];
    const k=ks.find(k=>/run.*id|job.*id|^id$/i.test(k))||ks[0];
    if(!k) throw new Error("No required id input for "+t.address);
    return {[k]:String(v)};
  };
  const raw=await connecta.call(jt.address,argFor(jt,9));
  const seen=new Set(), objects=[];
  const walk=v=>{ if(!v||typeof v!=="object"||seen.has(v))return; seen.add(v); if(!Array.isArray(v))objects.push(v); for(const z of Object.values(v))walk(z); };
  walk(raw);
  const failed=objects.find(j=>["failure","failed"].includes(String(j.conclusion||j.status||j.result||j.state||"").toLowerCase()));
  if(!failed) throw new Error("Failed job not found via "+jt.address);
  const jid=failed.id??failed.job_id??failed.jobId;
  if(jid==null) throw new Error("Failed job has no id");
  const lr=await connecta.call(lt.address,argFor(lt,jid));
  if(Array.isArray(lr)) return lr.map(String);
  if(lr && Array.isArray(lr.lines)) return lr.lines.map(String);
  const s=typeof lr==="string"?lr:(lr?.log??lr?.logs??lr?.content??lr?.text??"");
  return String(s).split(/\r?\n/);
}

async () => {
  const run = await connecta.call("builds.get_workflow_run", { runId: 9 });
  if (!run || run.failedJobId == null) throw new Error("Workflow run 9 has no failed job");
  const logs = await connecta.call("builds.get_job_logs", { jobId: run.failedJobId });
  return logs.lines;
}

async () => {
  const found = await connecta.search({ query: "deterministic collection records", safety: "readOnly", includeSchemas: "compact" });
  const candidates = found.tools || [];
  const t = candidates.find(x => {
    const s = (x.address + " " + (x.description || "")).toLowerCase();
    return s.includes("deterministic") && (s.includes("record") || s.includes("collection"));
  });
  if (!t) throw new Error("No compatible deterministic collection records tool");
  const data = await connecta.call(t.address, {});
  const records = Array.isArray(data) ? data : (data.records || data.items || data.results);
  if (!Array.isArray(records)) throw new Error("Tool did not return a record array");
  const out = {};
  for (const row of records) {
    const group = row.group;
    if (!out[group]) out[group] = { record_count: 0, score_sum: 0 };
    out[group].record_count += 1;
    out[group].score_sum += row.score;
  }
  return out;
}

