async () => {
  const runSearch = await connecta.search({ query: "workflow run response", safety: "readOnly", includeSchemas: "compact" });
  const docSearch = await connecta.search({ query: "document search text", safety: "readOnly", includeSchemas: "compact" });
  const runTool = runSearch.tools.find(t =>
    /workflow/i.test(t.address + " " + (t.description || "")) &&
    /run/i.test(t.address + " " + (t.description || "")) &&
    Array.isArray(t.requiredInputKeys) &&
    t.requiredInputKeys.length === 1
  );
  const searchTool = docSearch.tools.find(t =>
    /document/i.test(t.address + " " + (t.description || "")) &&
    /search/i.test(t.address + " " + (t.description || "")) &&
    Array.isArray(t.requiredInputKeys) &&
    t.requiredInputKeys.length === 1
  );
  if (!runTool) throw new Error("No compatible workflow-run read tool found: " + JSON.stringify(runSearch.tools));
  if (!searchTool) throw new Error("No compatible document-search read tool found: " + JSON.stringify(docSearch.tools));
  const runKey = runTool.requiredInputKeys[0];
  const queryKey = searchTool.requiredInputKeys[0];
  const calls = await connecta.batch([
    { address: runTool.address, args: { [runKey]: 9 } },
    { address: searchTool.address, args: { [queryKey]: "staged customer rollout" } }
  ]);
  if (!calls[0].ok) throw new Error("Workflow call failed: " + JSON.stringify(calls[0]));
  if (!calls[1].ok) throw new Error("Document search failed: " + JSON.stringify(calls[1]));
  const workflowRun = calls[0].data;
  const rawSearch = calls[1].data;
  let launchPlanMatches;
  if (Array.isArray(rawSearch)) launchPlanMatches = rawSearch;
  else {
    const candidateKeys = ["results", "matches", "documents", "items"];
    const key = candidateKeys.find(k => Array.isArray(rawSearch?.[k]));
    if (!key) throw new Error("Document search response has no result array: " + JSON.stringify(rawSearch));
    launchPlanMatches = rawSearch[key];
  }
  return { workflowRun, launchPlanMatches };
}

