async () => {
  const found = await connecta.search({ query: "list routing incidents", safety: "readOnly", includeSchemas: "compact" });
  const candidates = found.tools.filter(t => /incident/i.test(t.address + " " + (t.description || "")));
  if (!candidates.length) throw new Error("No incident listing tool found");
  const best = candidates.find(t => /list.*incident|incident.*list/i.test(t.address + " " + (t.description || ""))) || candidates[0];
  const required = best.requiredInputKeys || [];
  if (required.length) throw new Error("Incident listing tool requires unsupported inputs: " + required.join(","));
  const data = await connecta.call(best.address, {});
  const arr = Array.isArray(data) ? data : (data.incidents || data.items || data.results || []);
  const active = arr.filter(x => {
    const status = String(x.status ?? x.state ?? "").toLowerCase();
    const title = String(x.title ?? x.name ?? "");
    const routing = [x.type, x.category, x.service, x.team, x.component, title].filter(Boolean).join(" ").toLowerCase();
    return (status === "active" || status === "open" || status === "ongoing" || status === "investigating" || status === "identified" || status === "monitoring") && routing.includes("routing");
  });
  return { count: active.length, titles: active.map(x => String(x.title ?? x.name ?? "")) };
}

